INSERT INTO `lc_article` VALUES (32,'关于我们',18,'','<p>关于 LBMA</p>\r\n\r\n<h1>独立的全球贵金属权威机构</h1>\r\n\r\n<p>我们通过提升行业标准和开发市场解决方案，确保全球贵金属行业具有最高水平的领导力、诚信度和透明度。</p>\r\n\r\n<h2>我们</h2>\r\n\r\n<h3>合格交割</h3>\r\n\r\n<p>保障 Loco London 市场的金属品质</p>\r\n\r\n<p>全球贵金属准则</p>\r\n\r\n<p>提高市场的稳健、公平、有效性和适当的透明性</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>负责任采购</h3>\r\n\r\n<p>LBMA 确保金属的采购合乎道德</p>\r\n\r\n<p>了解更多详情</p>\r\n\r\n<h3>市场解决方案</h3>\r\n\r\n<p>我们指明市场需求，并找到解决方案对系统和流程进行改进。</p>\r\n\r\n<h3>实体市场</h3>\r\n\r\n<p>为了支持实物贸易和实物交割，我们扩大了&ldquo;合格交割&rdquo;和&ldquo;负责任采购&rdquo;的工作范围，将我们名单中由精炼厂生产的、用于零售市场的小件产品也涵盖其中。而我们也正在探索如何使用科技从源头强化供应链。</p>\r\n\r\n<h3>金融市场</h3>\r\n\r\n<p>我们不仅希望保证贸易业务的增长，也希望它们对新客户、现有客户和市场参与者保持足够的吸引力。在我们推出 LBMA 贸易数据报表服务之前，市场流动性一直难以量化。如今，LBMA 贸易数据正在提高 Loco London 贵金属市场的透明度，也展示了该市场的流动性。</p>\r\n\r\n<h3>Loco London 贵金属市场</h3>\r\n\r\n<p>Loco London 贵金属市场是全球最大、最古老的贵金属金融市场。来自全球各地的市场参与者和客户，以直接交易的方式进行着各种定制化交易。该市场黄金的日均交易量为 500 亿美元。</p>\r\n','2023-07-25 14:23:33',1,NULL),(33,'帮助中心',19,'','<p>取款时间为：14:00&mdash;20:00。请悉知！单笔最低取款金额 1000&nbsp; LBMA 在全球 20 多个国家内拥有超过 145 家会员公司。 这些公司有的是金融机构，有的是采矿、精炼、运输、贸易、保险和制造企业，它们在成为 LBMA 会员后，都享受到了大量权益。取款时间为：14:00-20:00 。请悉知！</p>\r\n\r\n<p>会员权益</p>\r\n\r\n<p>LBMA 会员能够洞悉市场，并和我们一起制定行业的未来发展方向。会员能够获得专业的知识、资源和建议。会员可以协助我们提升行业标准并开发市场。会员也可以通过知识、人脉和专业技能，优化自己的商业网络。</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2>会员种类</h2>\r\n\r\n<p>贵公司适合成为哪类会员、该类会员有何要求？阅读下方内容，了解更多详情。</p>\r\n\r\n<h3>正式会员</h3>\r\n\r\n<p>LBMA 的正式会员资格面向位于英国及海外的公司。 每一位正式会员都必须从事与伦敦黄金市场密切相关的经营活动。</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>造市会员</h3>\r\n\r\n<p>造市会员与正式成员享受同样的权利，但承担有额外的责任：在伦敦交易日内，以商定的最低数量和票期，彼此对黄金和白银进行竞价和报价。</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>附属会员</h3>\r\n\r\n<p>LBMA 的附属会员资格面向一系列的国际市场参与者、服务提供商、技术提供商、交易所、中介机构。</p>\r\n','2023-07-26 17:16:58',1,0),(36,'2023.12.5.ประกาศและข้อกำหนด',9,'','<p>เรียนผู้ใช้งานทุนท่านค่ะ กรณีฝาก-ถอนเงิน จะต้องแจ้งที่&quot;ฝ่ายบริการลูกค้า&quot;เท่านั้น หากทำรายการฝากถอนที่ไม่ได้ผ่านทาง&quot;ฝ่ายบริการลูกค้า&quot;หากเกิดปัญหาทางเราจะไม่รับผิดชอบใดๆทุกกรณีค่ะ</p>\r\n','2024-02-06 03:48:48',1,NULL);
