INSERT INTO `lc_prize` VALUES (1,0,'2020-06-30 19:39:00','<p>凡是投资指定项目的用户均可获得一次抽奖机会，抽奖机会可以累加！ 抽中现金的用户，奖金将自动打款到您的余额，您可以自行提现或者进行投资； 抽中实物的用户，请联系在线客服进行兑换，联系时请备注您的会员账号，以便客服查验。</p>\r\n','','价值13888元苹果电脑一台',2,0.00,0.00,'恭喜您获得一等奖价值13888元苹果电脑一台，请联系在线客服办理领取礼品！','价值6488元华为p40pro5G版 8',2,0.00,0.00,'恭喜您获得二等奖价值6488元华为p40pro5G版 8+256G全网通手机一台，请联系在线客服办理领取礼品！','现金红包3888元',1,3888.00,0.00,'恭喜您获得价3888元现金大礼，已派送至您的会员账户！','500元话费',2,0.00,0.00,'恭喜您获得四等奖500话费，请联系在线客服办理领取礼品！','现金红包20.88元',1,20.88,1.00,'恭喜您获得现金20.88元，已派送至您的会员账户！','谢谢参与',1,0.88,99.00,'恭喜您获得价0.88元现金，已派送至您的会员账户！');
